package com.collegeerp.erp.email.entity;import com.collegeerp.erp.common.entity.BaseAuditEntity;import com.collegeerp.erp.user.entity.User;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="email_verification_tokens",indexes=@Index(name="idx_verify_hash",columnList="token_hash",unique=true))public class EmailVerificationToken extends BaseAuditEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)private User user;@Column(nullable=false,length=64)private String tokenHash;@Column(nullable=false)private LocalDateTime expiresAt;private LocalDateTime usedAt,revokedAt;public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getTokenHash(){return tokenHash;}public void setTokenHash(String v){tokenHash=v;}public LocalDateTime getExpiresAt(){return expiresAt;}public void setExpiresAt(LocalDateTime v){expiresAt=v;}public LocalDateTime getUsedAt(){return usedAt;}public void setUsedAt(LocalDateTime v){usedAt=v;}public LocalDateTime getRevokedAt(){return revokedAt;}public void setRevokedAt(LocalDateTime v){revokedAt=v;}}
